import { clear, element } from './dom';
import type { HudState } from './types';

export class Hud {
  readonly element = element('section', 'game-hud');
  private readonly hole = element('div', 'hud-hole');
  private readonly strokes = element('div', 'hud-strokes');
  private readonly status = element('div', 'hud-status');
  private readonly powerFill = element('div', 'power-meter__fill');
  private readonly powerValue = element('span', 'power-meter__value');

  constructor() {
    const info = element('div', 'hud-info');
    info.append(this.hole, this.strokes, this.status);
    const meter = element('div', 'power-meter');
    const label = element('div', 'power-meter__label', 'POWER');
    label.append(this.powerValue);
    const track = element('div', 'power-meter__track');
    track.setAttribute('role', 'meter');
    track.append(this.powerFill, element('i', 'power-meter__max'));
    meter.append(label, track);
    this.element.append(info, meter);
  }

  render(state: HudState): void {
    const power = Math.max(0, Math.min(1, state.power));
    this.hole.textContent = `HOLE ${state.holeNumber}/${state.holeCount} · ${state.holeName} · PAR ${state.par}`;
    this.strokes.textContent = `STROKES ${state.strokes}`;
    this.status.textContent = state.statusText ?? (state.canShoot ? 'READY' : 'BALL IN MOTION');
    this.status.dataset.ready = String(state.canShoot);
    this.powerFill.style.width = `${Math.round(power * 100)}%`;
    this.powerValue.textContent = `${Math.round(power * 100)}%`;
    const track = this.element.querySelector<HTMLElement>('[role="meter"]');
    track?.setAttribute('aria-valuemin', '0');
    track?.setAttribute('aria-valuemax', '100');
    track?.setAttribute('aria-valuenow', String(Math.round(power * 100)));
  }

  destroy(): void { clear(this.element); this.element.remove(); }
}
