import { clear, element, signed } from './dom';
import type { ScoreboardState, UiPlayer } from './types';

function row(player: UiPlayer, position: number): HTMLElement {
  const item = element('div', `scoreboard__row${player.isLocal ? ' is-local' : ''}`);
  item.dataset.playerId = player.id;
  const marker = element('span', 'scoreboard__color');
  marker.style.backgroundColor = player.color;
  item.append(
    element('span', 'scoreboard__rank', String(position)),
    marker,
    element('span', 'scoreboard__name', player.name),
    element('span', 'scoreboard__hole', String(player.strokes)),
    element('span', 'scoreboard__total', String(player.totalStrokes)),
    element('span', 'scoreboard__par', signed(player.parDelta)),
  );
  return item;
}

export class Scoreboard {
  readonly element = element('section', 'scoreboard overlay-panel');
  render(state: ScoreboardState): void {
    clear(this.element);
    this.element.append(element('h2', '', `SCOREBOARD · HOLE ${state.holeNumber}/${state.holeCount}`));
    const head = element('div', 'scoreboard__row scoreboard__head');
    head.append(element('span', '', '#'), element('span'), element('span', '', 'PLAYER'), element('span', '', 'HOLE'), element('span', '', 'TOTAL'), element('span', '', 'PAR'));
    this.element.append(head);
    const sorted = [...state.players].sort((a, b) => a.totalStrokes - b.totalStrokes || a.parDelta - b.parDelta);
    sorted.slice(0, 8).forEach((player, index) => this.element.append(row(player, index + 1)));
  }
}
