import { clear, element, signed } from './dom';
import type { MatchResultsState } from './types';

export class PauseOverlay {
  readonly element = element('section', 'pause-overlay overlay-panel');
  constructor(onResume?: () => void, onSettings?: () => void, onQuit?: () => void) {
    this.element.append(element('h2', '', 'PAUSED'), element('p', '', 'Take a breather. Your match is waiting.'));
    for (const [label, action] of [['RESUME', onResume], ['SETTINGS', onSettings], ['QUIT MATCH', onQuit]] as const) {
      const button = element('button', 'ui-button', label);
      if (action) button.addEventListener('click', action);
      this.element.append(button);
    }
  }
}

export class LoadingOverlay {
  readonly element = element('section', 'loading-overlay overlay-panel');
  private readonly message = element('p', '', 'Preparing course…');
  private readonly fill = element('div', 'loading-progress__fill');
  constructor() {
    const track = element('div', 'loading-progress'); track.append(this.fill);
    this.element.append(element('h1', '', 'CRAZY PUTT ARENA'), this.message, track);
  }
  render(progress: number, message = 'Preparing course…'): void {
    const value = Math.max(0, Math.min(1, progress));
    this.message.textContent = message;
    this.fill.style.width = `${Math.round(value * 100)}%`;
  }
}

export class MatchResults {
  readonly element = element('section', 'match-results overlay-panel');
  render(state: MatchResultsState): void {
    clear(this.element);
    this.element.append(element('p', 'results-kicker', 'MATCH COMPLETE'), element('h1', '', state.courseName), element('p', '', `${state.holesPlayed} holes played`));
    const list = element('div', 'results-list');
    [...state.players].sort((a, b) => a.rank - b.rank).slice(0, 8).forEach(player => {
      const item = element('div', `results-row${player.rank === 1 ? ' is-winner' : ''}`);
      const rating = player.ratingAfter === undefined ? '—' : `${player.ratingAfter}${player.ratingBefore === undefined ? '' : ` (${signed(player.ratingAfter - player.ratingBefore)})`}`;
      item.append(element('strong', 'results-rank', `#${player.rank}`), element('span', 'results-name', player.name), element('span', '', `${player.totalStrokes} strokes`), element('span', '', signed(player.parDelta)), element('span', '', `Rating ${rating}`), element('span', '', `+${player.xpEarned ?? 0} XP`));
      list.append(item);
    });
    this.element.append(list);
  }
}
